def search_layer(q, ep, ef):
    visited = {ep}
    C = [ep]   # candidates, nearest first
    W = [ep]   # best ef found so far
    while C:
        c = pop_nearest(C)
        if dist(c, q) > dist(furthest(W), q):
            break  # nothing left can improve W
        for e in neighbors(c):
            if e in visited:
                continue
            visited.add(e)
            if len(W) < ef or dist(e, q) < dist(furthest(W), q):
                C.add(e)
                W.add(e)
                if len(W) > ef:
                    W.remove(furthest(W))
    return W

def select(g, cands, M):                  # cands: (dist, id), nearest first
    if not g.heuristic:
        return [e for _, e in cands[:M]]  # simple rule (Alg. 3)
    R = []
    for de, e in cands:                   # heuristic (Alg. 4)
        if len(R) == M:
            break
        if not R or de < g.d(g.x[e], R).min():
            R.append(e)                   # closer to q than to any kept
    return R

def insert(g, i):                         # Alg. 1 restricted to layer 0
    if i == 0:
        return
    g.links[i] = select(g, g.search(g.x[i], g.efc), g.M)
    for e in g.links[i]:                  # reverse links, then shrink
        g.links[e].append(i)
        if len(g.links[e]) > g.Mmax0:
            nb = g.links[e]
            g.links[e] = select(g, sorted(zip(g.d(g.x[e], nb), nb)), g.Mmax0)

